"""Evidence-led flow diagnosis and encrypted exchange size fingerprints."""
from statistics import median
from collections import defaultdict
import math


def exchange_fingerprints(transactions):
    rows = (transactions or {}).get("exchanges", [])
    groups = defaultdict(list)
    # Deterministic logarithmic size buckets (~25% width). Not identities;
    # near-boundary samples can split even if generated by the same operation.
    def bucket(n):
        return math.floor(math.log(max(1, n), 1.25))
    for row in rows:
        groups[(bucket(row["request_bytes"]), bucket(row["response_bytes"]))].append(row)
    result = []
    for members in sorted(groups.values(), key=lambda g: (-len(g), g[0]["id"])):
        result.append({"count": len(members), "request_median_bytes": round(median(x["request_bytes"] for x in members)),
                       "response_median_bytes": round(median(x["response_bytes"] for x in members)),
                       "wait_median_ms": round(median(x["response_delay_ms"] for x in members), 3),
                       "wait_max_ms": max(x["response_delay_ms"] for x in members),
                       "exchange_ids": [x["id"] for x in members]})
    return result


def diagnose(packets, transactions, window, rtt_ms, side, spread):
    findings = []
    def add(kind, strength, evidence, frames=None, interval=None):
        findings.append({"kind": kind, "strength": strength, "evidence": evidence,
                         "frames": frames or [], "interval": interval})
    for ep in window.get("episodes", [])[:30]:
        start, duration = ep.get("start_ms"), ep.get("duration_ms")
        add(ep["direction"].capitalize()+" receiver window closed", "observed",
            "Explicit zero-window advertisement; receiver flow control, not proof of network congestion.",
            ep.get("frames"), [start,start+duration] if start is not None and duration is not None else None)
    repeats = [p for p in packets if p.get("retrans")]
    recovery = [p for p in packets if p.get("dup_ack") or p.get("sack")]
    if repeats:
        add("TCP recovery / repeated data", "supported" if recovery else "possible",
            f"{len(repeats)} TShark retransmission indicators; {len(recovery)} duplicate ACK/SACK records. Capture artifacts and reordering remain alternatives.",
            [p["frame"] for p in repeats[:20]])
    if spread and not spread.get("insufficient") and spread.get("median_ms") and spread.get("p95_ms"):
        med, tail = spread["median_ms"],spread["p95_ms"]
        if tail >= max(3*med, med+20):
            add("Variable acknowledgement RTT", "supported",
                f"Median {med:g} ms, P95 {tail:g} ms. Queueing, delayed ACK, capture timing and asymmetry can contribute.")
    for x in (transactions or {}).get("exchanges", []):
        wait=x["response_delay_ms"]
        if not x.get("anomaly") and wait < max(250, 4*(rtt_ms or 0)):
            continue
        start,end=x["request_end_ms"],x["response_start_ms"]
        # Never use absence of flags as proof that transport is healthy.
        overlapping = any(ep.get("start_ms") is not None and ep.get("duration_ms") is not None
                          and ep["start_ms"] <= end and ep["start_ms"]+ep["duration_ms"] >= start
                          for ep in window.get("episodes", []))
        retry = any(start <= p["time_ms"] <= end for p in repeats)
        evidence=f"Exchange {x['id']}: {wait:g} ms observed response wait."
        if overlapping or retry:
            kind="Response wait with transport evidence"
            evidence += " Zero-window or retransmission indicator overlaps the wait."
        elif side=="server":
            kind="Possible server/application handling delay"
            evidence += " Near-server capture; no overlapping observed repeat or zero-window episode."
        elif side=="client" and rtt_ms and wait>rtt_ms:
            kind="Possible application or path delay"
            evidence += f" Wait exceeds estimated RTT by {wait-rtt_ms:.2f} ms; path variation remains possible."
        else:
            kind="Long response wait, cause undetermined"
        add(kind,"possible",evidence,[x["request_last_frame"],x["response_first_frame"]],[start,end])
        if len(findings)>=80:
            break
    if any(p.get("sliced") for p in packets):
        add("Capture truncation","observed","Some captured frames are shorter than their wire length; payload and protocol decoding may be incomplete.")
    return {"findings":findings,"basis":"Packet evidence, not probability scores. A single capture cannot conclusively assign every delay to client, server or network."}
